/**
 * Pure billing-period arithmetic: where a period ends, what it costs in full,
 * and what a mid-period change is worth. No I/O, so the renewal job, the
 * seat and plan changes and the tests all agree on the same numbers.
 *
 * Periods are UTC: "same time of day" means the UTC clock.
 */
import { PLAN_LIMITS } from "@/config/plan-limits";
import type { BillingInterval, PlanId } from "@/types/billing";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

export function monthsIn(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

/**
 * End of the period that starts at `start`. Same day of the month `n` months
 * later at the same time of day, clamped to that month's last day when it has
 * no such day (31 January → 28 February; 29 February → 28 February).
 */
export function periodEndFrom(start: Date, interval: BillingInterval): Date {
  const monthIndex = start.getUTCMonth() + monthsIn(interval);
  const year = start.getUTCFullYear() + Math.floor(monthIndex / 12);
  const month = ((monthIndex % 12) + 12) % 12;
  const lastDay = new Date(Date.UTC(year, month + 1, 0)).getUTCDate();

  return new Date(
    Date.UTC(
      year,
      month,
      Math.min(start.getUTCDate(), lastDay),
      start.getUTCHours(),
      start.getUTCMinutes(),
      start.getUTCSeconds(),
      start.getUTCMilliseconds(),
    ),
  );
}

/** Full charge in cents for one period: price per seat × seats × months. */
export function fullPeriodChargeCents(
  plan: PlanId,
  seats: number,
  interval: BillingInterval,
): number {
  return (
    PLAN_LIMITS[plan].priceCentsPerSeatMonthly * seats * monthsIn(interval)
  );
}

/** Whole days in a period, rounded, and never less than one. */
export function daysInPeriod(periodStart: Date, periodEnd: Date): number {
  return Math.max(
    1,
    Math.round((periodEnd.getTime() - periodStart.getTime()) / MS_PER_DAY),
  );
}

/**
 * Whole or started days from `at` to the period end; a partial day counts as
 * a full one, and there are none once the period end has been reached.
 */
export function daysLeftInPeriod(periodEnd: Date, at: Date): number {
  const remaining = periodEnd.getTime() - at.getTime();
  if (remaining <= 0) return 0;
  return Math.ceil(remaining / MS_PER_DAY);
}

/**
 * Scales a full-period amount to the part of the period left at `at`, rounded
 * down to whole cents.
 */
export function prorateCents(
  fullCents: number,
  periodStart: Date,
  periodEnd: Date,
  at: Date,
): number {
  if (fullCents <= 0) return 0;
  const left = daysLeftInPeriod(periodEnd, at);
  if (left === 0) return 0;
  return Math.floor(
    (fullCents * left) / daysInPeriod(periodStart, periodEnd),
  );
}

