/** A plan change ends the trial: the org has made a deliberate choice. */
export async function updateSubscriptionPlan(
  orgId: OrgId,
  plan: PlanId,
  interval: BillingInterval,
  period?: Period,
): Promise<Subscription> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .update(subscriptions)
    .set({
      plan,
      interval,
      status: "active",
      ...periodPatch(period),
      updatedAt: stamp,
    })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

/** Moves the subscription's current period on; the plan is untouched. */
export async function setSubscriptionPeriod(
  orgId: OrgId,
  period: Period,
): Promise<Subscription> {
  const row = getDb()
    .update(subscriptions)
    .set({ ...periodPatch(period), updatedAt: toIsoTimestamp(new Date()) })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

/**
 * A cancellation that has taken effect: the org is back on the free plan,
 * active, with nothing pending and a fresh monthly period.
 */
export async function moveSubscriptionToFree(
  orgId: OrgId,
  period: Period,
): Promise<Subscription> {
  const row = getDb()
    .update(subscriptions)
    .set({
      plan: "free",
      interval: "monthly",
      status: "active",
      cancelAt: null,
      ...periodPatch(period),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

/** Every subscription of every live (non-archived) workspace. */
export async function listSubscriptionsForRenewal(): Promise<
  readonly Subscription[]
> {
  const rows = getDb()
    .select({ subscription: subscriptions })
    .from(subscriptions)
    .innerJoin(organizations, eq(organizations.id, subscriptions.orgId))
    .where(isNull(organizations.archivedAt))
    .all();

  return rows.map((row) => toSubscription(row.subscription));
}

function periodPatch(period: Period | undefined): {
  currentPeriodStart?: IsoTimestamp;
  currentPeriodEnd?: IsoTimestamp;
} {
  if (!period) return {};
  return {
    currentPeriodStart: period.start,
    currentPeriodEnd: period.end,
  };
}

