 * invoice count plus one; the count and the insert run in one synchronous
 * database call chain, so two writers cannot pick the same number, and the
 * unique index on (org, number) backs that up.
 */
export async function issueInvoice(
  orgId: OrgId,
  amountCents: number,
  period: InvoicePeriod,
): Promise<Invoice> {
  const stamp = toIsoTimestamp(new Date());
  const existing = getDb()
    .select({ total: count() })
    .from(invoices)
    .where(orgPredicate(invoices.orgId, orgId))
    .get();
