import { z } from "zod";
import type { NotificationKind } from "@/types/notification";
import {
  notificationIdSchema,
  orgIdSchema,
  pageRequestSchema,
  userIdSchema,
} from "./common";

export const notificationKindSchema = z.enum([
  "issue_assigned",
  "issue_status_changed",
  "issue_due_soon",
  "issue_overdue",
  "comment_created",
  "comment_mention",
  "member_invited",
  "member_joined",
  "project_archived",
  "plan_limit_reached",
  "digest_ready",
]);

export const notificationChannelSchema = z.enum(["in_app", "email", "webhook"]);

export const markNotificationReadSchema = z.object({
  orgId: orgIdSchema,
  notificationId: notificationIdSchema,
});

export const markAllNotificationsReadSchema = z.object({
  orgId: orgIdSchema,
});

export const listNotificationsSchema = z
  .object({
    orgId: orgIdSchema,
    recipientId: userIdSchema,
    unreadOnly: z.boolean().default(false),
    kind: z.array(notificationKindSchema).optional(),
  })
  .extend(pageRequestSchema.shape);

export const updateNotificationPreferenceSchema = z.object({
  orgId: orgIdSchema,
  userId: userIdSchema,
  kind: notificationKindSchema,
  inApp: z.boolean(),
  email: z.boolean(),
  digestOnly: z.boolean(),
});

const _kindParity: NotificationKind = "comment_mention" satisfies z.infer<
  typeof notificationKindSchema
>;
void _kindParity;

export type MarkNotificationReadInput = z.infer<
  typeof markNotificationReadSchema
>;
export type ListNotificationsInput = z.infer<typeof listNotificationsSchema>;
export type UpdateNotificationPreferenceInput = z.infer<
  typeof updateNotificationPreferenceSchema
>;

/**
 * Presentation helpers for the audit trail.
 *
 * `ActivityEvent.summary` is written by the service layer and is authoritative;
 * these helpers only supply the verb chip and the day grouping the feed and the
 * per-issue panel both render, so the two views never disagree about what a
 * day boundary is.
 */
import type { ActivityAction, ActivityEvent, ActivityGroup } from "@/types/activity";

export const ACTIVITY_LABELS: Readonly<Record<ActivityAction, string>> = {
  "organization.updated": "updated the organization",
  "project.created": "created a project",
  "project.updated": "updated a project",
  "project.archived": "archived a project",
  "project.restored": "restored a project",
  "issue.created": "created an issue",
  "issue.updated": "updated an issue",
  "issue.status_changed": "changed status",
  "issue.assigned": "assigned an issue",
  "issue.archived": "archived an issue",
  "issue.restored": "restored an issue",
  "comment.created": "commented",
  "comment.updated": "edited a comment",
  "comment.deleted": "deleted a comment",
  "member.invited": "invited a member",
  "member.joined": "joined the organization",
  "member.role_changed": "changed a role",
  "member.removed": "removed a member",
  "billing.plan_changed": "changed the plan",
  "flag.toggled": "toggled a feature flag",
};

export function activityLabel(action: ActivityAction): string {
  return ACTIVITY_LABELS[action] ?? action;
}

/** The calendar day an event belongs to, in UTC (`YYYY-MM-DD`). */
export function activityDay(event: ActivityEvent): string {
  return event.occurredAt.slice(0, 10);
}

/**
 * Groups a flat event list into the day buckets `ActivityFeed` consumes,
 * newest day first and newest event first within a day.
 */
export function groupEventsByDay(
  events: readonly ActivityEvent[],
): readonly ActivityGroup[] {
  const byDay = new Map<string, ActivityEvent[]>();

  for (const event of events) {
    const day = activityDay(event);
    const bucket = byDay.get(day) ?? [];
    bucket.push(event);
    byDay.set(day, bucket);
  }

  return [...byDay.entries()]
    .sort(([a], [b]) => b.localeCompare(a))
    .map(([day, bucket]) => ({
      day,
      events: [...bucket].sort((a, b) =>
        b.occurredAt.localeCompare(a.occurredAt),
      ),
    }));
}

"use client";

/**
 * Per-kind channel matrix; the digest column is hidden unless `digest_email`
 * is on.
 *
 * Must call (do not reimplement): isEnabled
 */
import { Switch } from "@/components/ui/switch";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeaderCell,
  TableRow,
} from "@/components/ui/table";
import { ANONYMOUS_FLAG_CONTEXT } from "@/hooks/flag-context";
import { useFormAction } from "@/hooks/use-form-action";
import { isEnabled } from "@/lib/feature-flags";
import type { UpdateNotificationPreferenceInput } from "@/schemas/notification";
import type { ActionResult } from "@/types/api";
import type { OrgId, UserId } from "@/types/common";
import type { FeatureFlagSnapshot } from "@/types/feature-flag";
import type {
  NotificationKind,
  NotificationPreference,
} from "@/types/notification";
import type { ReactElement } from "react";

export type NotificationPreferencesFormProps = {
  orgId: OrgId;
  userId: UserId;
  preferences: readonly NotificationPreference[];
  flags: FeatureFlagSnapshot;
  onSubmit: (
    input: UpdateNotificationPreferenceInput,
  ) => Promise<ActionResult<NotificationPreference>>;
};

const KIND_LABELS: Readonly<Record<NotificationKind, string>> = {
  issue_assigned: "Issue assigned to me",
  issue_status_changed: "Issue status changed",
  issue_due_soon: "Issue due soon",
  issue_overdue: "Issue overdue",
  comment_created: "New comment",
  comment_mention: "I was mentioned",
  member_invited: "Member invited",
  member_joined: "Member joined",
  project_archived: "Project archived",
  plan_limit_reached: "Plan limit reached",
  digest_ready: "Daily digest ready",
};

export function NotificationPreferencesForm(
  props: NotificationPreferencesFormProps,
): ReactElement | null {
  const { orgId, userId, preferences, flags, onSubmit } = props;
  const { submit, pending } = useFormAction(onSubmit);

  const digestOn =
    flags.digest_email === true ||
    isEnabled("digest_email", ANONYMOUS_FLAG_CONTEXT);

  function update(
    preference: NotificationPreference,
    patch: Partial<
      Pick<NotificationPreference, "inApp" | "email" | "digestOnly">
    >,
  ): void {
    void submit({
      orgId,
      userId,
      kind: preference.kind,
      inApp: patch.inApp ?? preference.inApp,
      email: patch.email ?? preference.email,
      digestOnly: patch.digestOnly ?? preference.digestOnly,
    });
  }

  return (
    <Table caption="Notification preferences">
      <TableHead>
        <TableRow>
          <TableHeaderCell>Event</TableHeaderCell>
          <TableHeaderCell>In app</TableHeaderCell>
          <TableHeaderCell>Email</TableHeaderCell>
          {digestOn ? <TableHeaderCell>Digest only</TableHeaderCell> : null}
        </TableRow>
      </TableHead>

      <TableBody>
        {preferences.map((preference) => (
          <TableRow key={preference.kind}>
            <TableCell>{KIND_LABELS[preference.kind]}</TableCell>

            <TableCell className="w-24">
              <Switch
                name={`${preference.kind}-in-app`}
                checked={preference.inApp}
                disabled={pending}
                onChange={(checked) => update(preference, { inApp: checked })}
              />
            </TableCell>

            <TableCell className="w-24">
              <Switch
                name={`${preference.kind}-email`}
                checked={preference.email}
                disabled={pending}
                onChange={(checked) => update(preference, { email: checked })}
              />
            </TableCell>

            {digestOn ? (
              <TableCell className="w-28">
                <Switch
                  name={`${preference.kind}-digest`}
                  checked={preference.digestOnly}
                  // Batching only makes sense when email is on at all.
                  disabled={pending || !preference.email}
                  onChange={(checked) =>
                    update(preference, { digestOnly: checked })
                  }
                />
              </TableCell>
            ) : null}
          </TableRow>
        ))}
      </TableBody>
    </Table>
  );
}

