/**
 * Writes an invoice for one period and announces it, once. A zero amount
 * writes nothing. Shared by the renewal job and the mid-period changes so
 * every invoice is numbered, published, audited and announced the same way.
 */
export async function issueInvoice(
  orgId: OrgId,
  amountCents: number,
  period: InvoicePeriod,
): Promise<Invoice | null> {
  if (amountCents <= 0) return null;

  const invoice = await invoiceRepo.issueInvoice(orgId, amountCents, period);

  await emit("billing.invoice_issued", {
    orgId,
    actorId: null,
    occurredAt: toIsoTimestamp(new Date()),
    invoiceId: invoice.id,
    invoiceNumber: invoice.number,
    amountCents,
    periodStart: invoice.periodStart,
    periodEnd: invoice.periodEnd,
  });

  return invoice;
}

/**
 * What a plan change costs, and whether it moves the period. Trials and the
 * free plan are free to switch; leaving free starts a fresh, fully billed
 * period; between paid plans an active subscription pays for the rise in
 * price, prorated, and a downgrade or same-price move pays nothing.
 */
function planChangeCharge(
  current: Subscription,
  input: ChangePlanInput,
  now: Date,
): {
  cents: number;
  invoicePeriod: InvoicePeriod;
  period?: Period;
} {
  const unchanged = currentPeriodOf(current);

  if (current.status === "trialing") {
    return { cents: 0, invoicePeriod: unchanged };
  }

  if (current.plan === "free") {
    if (input.plan === "free") return { cents: 0, invoicePeriod: unchanged };

    const start = toIsoTimestamp(now);
    const end = toIsoTimestamp(periodEndFrom(now, input.interval));
    return {
      cents: fullPeriodChargeCents(input.plan, current.seats, input.interval),
      invoicePeriod: { start, end },
      period: { start, end },
    };
  }

  if (input.plan === "free" || current.status !== "active") {
    return { cents: 0, invoicePeriod: unchanged };
  }

  const rise =
    getPlanLimits(input.plan).priceCentsPerSeatMonthly -
    getPlanLimits(current.plan).priceCentsPerSeatMonthly;
  if (rise <= 0) return { cents: 0, invoicePeriod: unchanged };

  return {
    cents: prorateCents(
      rise * current.seats * monthsIn(current.interval),
      new Date(current.currentPeriodStart),
      new Date(current.currentPeriodEnd),
      now,
    ),
    invoicePeriod: unchanged,
  };
}

/** Paid and active: the only state in which a mid-period change is charged. */
function isBilledNow(subscription: Subscription): boolean {
  return subscription.status === "active" && subscription.plan !== "free";
}

function currentPeriodOf(subscription: Subscription): InvoicePeriod {
  return {
    start: subscription.currentPeriodStart,
    end: subscription.currentPeriodEnd,
  };
}

