/**
 * Renews active subscriptions whose period has ended, invoices every paid
 * period, and ends cancellations on their date.
 *
 * Must call (do not reimplement): emit, issueInvoice, periodEndFrom, fullPeriodChargeCents
 */
import { fullPeriodChargeCents, periodEndFrom } from "@/lib/billing-period";
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import type { Period } from "@/server/repositories/subscription-repository";
import { issueInvoice } from "@/server/services/billing-service";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { Subscription } from "@/types/billing";
import type { IsoTimestamp, OrgId } from "@/types/common";
import type { JobResult } from "@/server/jobs/types";

/** Where a cancelled subscription lands once its cancellation takes effect. */
const FALLBACK_PLAN = "free" as const;

const logger = createLogger("billing-renewal-job");

/**
 * One pass over every live workspace. Replay-safe: a renewed subscription has
 * its period end after `now`, and an ended cancellation is no longer
 * `canceled`, so a second run at the same instant finds nothing to do.
 */
export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    const subscriptions = await subscriptionRepo.listSubscriptionsForRenewal();

    for (const subscription of subscriptions) {
      try {
        const changed =
          subscription.status === "active"
            ? await renewPeriods(subscription, now)
            : subscription.status === "canceled"
              ? await endCancellation(subscription, now)
              : false;

        if (changed) result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("billing renewal failed", {
          orgId: subscription.orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

/**
 * Creates one new period per elapsed interval until the current period end
 * lies after `now`. Each period is recorded before it is invoiced, so a failed
 * invoice write is never retried into a second charge for the same period.
 */
async function renewPeriods(
  subscription: Subscription,
  now: Date,
): Promise<boolean> {
  if (new Date(subscription.currentPeriodEnd) > now) return false;

  const orgId = subscription.orgId as OrgId;
  let start = new Date(subscription.currentPeriodEnd);

  do {
    const end = periodEndFrom(start, subscription.interval);
    const period: Period = {
      start: toIsoTimestamp(start),
      end: toIsoTimestamp(end),
    };

    await subscriptionRepo.setSubscriptionPeriod(orgId, period);

    if (subscription.plan !== FALLBACK_PLAN) {
      await issueInvoice(
        orgId,
        fullPeriodChargeCents(
          subscription.plan,
          subscription.seats,
          subscription.interval,
        ),
        period,
      );
    }

    start = end;
  } while (start <= now);

  return true;
}

/**
 * A cancellation reaching its date moves the workspace to the free plan as of
 * that date, with a fresh monthly period. Nothing is invoiced.
 */
async function endCancellation(
  subscription: Subscription,
  now: Date,
): Promise<boolean> {
  if (subscription.cancelAt === null) return false;

  const cancelAt = new Date(subscription.cancelAt);
  if (cancelAt > now) return false;

  const orgId = subscription.orgId as OrgId;
  const period: Period = {
    start: toIsoTimestamp(cancelAt),
    end: toIsoTimestamp(periodEndFrom(cancelAt, "monthly")),
  };

  await subscriptionRepo.moveSubscriptionToFree(orgId, period);

  if (subscription.plan !== FALLBACK_PLAN) {
    await emit("billing.plan_changed", {
      orgId,
      actorId: null,
      occurredAt: toIsoTimestamp(now),
      from: subscription.plan,
      to: FALLBACK_PLAN,
    });
  }

  return true;
}

export type { IsoTimestamp };

