/**
 * Period arithmetic and mid-period proration.
 */
import { describe, expect, it } from "vitest";
import {
  daysInPeriod,
  daysLeftInPeriod,
  fullPeriodChargeCents,
  periodEndFrom,
  prorateCents,
} from "@/lib/billing-period";

const at = (iso: string) => new Date(iso);

describe("lib/billing-period", () => {
  it("ends a monthly period on the same day of the next month", () => {
    expect(periodEndFrom(at("2026-12-15T00:00:00Z"), "monthly")).toEqual(
      at("2027-01-15T00:00:00Z"),
    );
  });

  it("clamps a monthly period to the last day when the next month is shorter", () => {
    expect(periodEndFrom(at("2026-01-31T00:00:00Z"), "monthly")).toEqual(
      at("2026-02-28T00:00:00Z"),
    );
  });

  it("carries a clamped day forward into the following period", () => {
    const first = periodEndFrom(at("2026-01-31T00:00:00Z"), "monthly");
    expect(periodEndFrom(first, "monthly")).toEqual(at("2026-03-28T00:00:00Z"));
  });

  it("ends an annual period on the same day and month of the next year", () => {
    expect(periodEndFrom(at("2027-06-10T09:30:00Z"), "annual")).toEqual(
      at("2028-06-10T09:30:00Z"),
    );
  });

  it("clamps an annual period from 29 February to 28 February", () => {
    expect(periodEndFrom(at("2028-02-29T00:00:00Z"), "annual")).toEqual(
      at("2029-02-28T00:00:00Z"),
    );
