/**
 * The renewal job: catch-up periods, one invoice per paid period, replay
 * safety, and cancellations taking effect on their date.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { runBillingRenewalJob } from "@/server/jobs/billing-renewal-job";
import * as invoiceRepo from "@/server/repositories/invoice-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

const NOW = new Date("2026-04-15T00:00:00Z");

const stamp = (iso: string) => toIsoTimestamp(new Date(iso));

describe("jobs/billing-renewal-job", () => {
  // A subscription three months behind gets three consecutive paid periods,
  // each invoiced once; a second pass at the same instant changes nothing.
  it("renews each elapsed period, invoices it, and is replay-safe", async () => {
    const tenant = await createTenant("renew-catch-up", "growth");
    await subscriptionRepo.updateSubscriptionPlan(
      tenant.org.id,
      "growth",
      "monthly",
      { start: stamp("2026-01-01T00:00:00Z"), end: stamp("2026-02-01T00:00:00Z") },
    );

    await runBillingRenewalJob(NOW);

    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices).toHaveLength(3);
    expect(invoices.map((invoice) => invoice.amountCents)).toEqual([1_900, 1_900, 1_900]);
    // Newest period first.
    expect(invoices[0]?.periodStart).toBe("2026-03-01T00:00:00.000Z");
    expect(invoices[0]?.periodEnd).toBe("2026-04-01T00:00:00.000Z");
    expect(invoices[0]?.currency).toBe("usd");
    expect(invoices[0]?.paidAt).toBeNull();

    const renewed = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(renewed?.currentPeriodStart).toBe("2026-04-01T00:00:00.000Z");
    expect(renewed?.currentPeriodEnd).toBe("2026-05-01T00:00:00.000Z");

    await runBillingRenewalJob(NOW);

    expect(await invoiceRepo.listInvoices(tenant.org.id)).toHaveLength(3);
  });

  // The cancellation date, not the period end, decides when the org moves to free.
  it("ends a cancellation on its date, without an invoice, announcing it once", async () => {
    const tenant = await createTenant("cancel-date", "growth");
    await subscriptionRepo.updateSubscriptionPlan(
      tenant.org.id,
      "growth",
      "monthly",
      { start: stamp("2026-03-01T00:00:00Z"), end: stamp("2026-04-01T00:00:00Z") },
    );
    await subscriptionRepo.cancelSubscription(
      tenant.org.id,
      stamp("2026-04-10T00:00:00Z"),
    );

    const announced: unknown[] = [];
    const off: Unsubscribe = subscribe("billing.plan_changed", (payload) => {
      if (payload.orgId === tenant.org.id) announced.push(payload);
    });

    await runBillingRenewalJob(new Date("2026-04-09T00:00:00Z"));
    const before = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(before).toMatchObject({ plan: "growth", status: "canceled" });

    await runBillingRenewalJob(NOW);
    await runBillingRenewalJob(NOW);
    off();

    const after = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(after).toMatchObject({
      plan: "free",
      interval: "monthly",
      status: "active",
      cancelAt: null,
      currentPeriodStart: "2026-04-10T00:00:00.000Z",
      currentPeriodEnd: "2026-05-10T00:00:00.000Z",
    });
    expect(announced).toEqual([
      expect.objectContaining({ from: "growth", to: "free", actorId: null }),
    ]);
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toHaveLength(0);
  });
});

